import {
  Component,
  Prop,
  h,
  Host,
  Watch,
  State,
  forceUpdate,
  Element,
  Fragment,
  Event,
  EventEmitter,
} from '@stencil/core';
import { getListWidth, getListHeight, getDotCount, hasMoreSlide } from './utils';
import { debounce } from 'lodash-es';
import { dir } from '@src/shared/i18n';
import { DetailArgs } from '@src/shared/dom';

@Component({
  tag: 'ks-carousel',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsCarousel {
  @Element() el!: HTMLKsCarouselElement;

  private first?: HTMLElement;
  private last?: HTMLElement;
  /** Indicates whether to display pagination controls, and how to display them.
   * - If set to `true`, dots pagination will be shown when the number of slides <= **6**, otherwise numeric pagination will be shown.
   * - If set to `'dots'`, dots pagination will always be shown.
   * - If set to `'numeric'`, numeric pagination will always be shown.
   */
  @Prop() pagination: boolean | 'dots' | 'numeric' = false;
  /**
   * Indicates whether to display navigation arrows for the carousel. This can be a boolean value or set to `'overlay'` to show arrows over the slides.
   * - If set to `true`, arrows will be displayed.
   * - If set to `false`, arrows will be hidden.
   * - If set to `'overlay'`, arrows will be shown over the slides.
   */
  @Prop() arrows: boolean | 'overlay' = false;
  /** Indicates whether the carousel should play automatically. If set to `true`, the slides will transition automatically at a specified interval. */
  @Prop() autoplay = false;
  /** The duration (in milliseconds) between each slide transition when `autoplay` is `true`. This value determines how long each slide is displayed before transitioning to the next one. Effective only if `autoplay` is `true`. */
  @Prop() autoplaySpeed = 3000;
  /**
   * Indicates whether the carousel should loop continuously. If set to `true`, the carousel will loop back to the first slide after reaching the last slide. \
   * Currently only effective if `slidesToShow` and `slidesToScroll` are not greater than `1`.
   */
  @Prop() infinite = true;
  /** The number of slides to display at once in the carousel. This value determines how many slides are shown in the viewport simultaneously. */
  @Prop() slidesToShow = 1;
  /** The number of slides to scroll at a time when navigating through the carousel. This value determines how many slides are moved during each transition. */
  @Prop() slidesToScroll = 1;
  /** The index of the initial slide to display when the carousel is first rendered. This value determines which slide is shown at the start. */
  @Prop() defaultCurrent = 0;
  /** @private 内部属性，请勿使用 */
  @Prop() bulletinMode = false;
  /** Triggers when the current slide index changes, with trigger info. */
  @Event() ksCurrentChange!: EventEmitter<
    DetailArgs<
      [number, { trigger: 'arrowButton' | 'pagination' | 'autoplay' | 'prop'; direction: 'forward' | 'backward' }]
    >
  >;

  @State() containerWidth = 0;

  @State() width = 0;

  @State() sliderWidth = 0;

  @State() height = 0;

  @State() listWidth = 0;

  @State() currentIndex = 0;

  @State() clickArrow: 'left' | 'right' | 'none' = 'none';

  @State() count = 0;

  @State() dotsCount = 0;

  @State() dotsIndex = 1;

  @State() autoplaying = 'playing';

  // @ts-expect-error TYPE_FIXME. Please Fix the below strict mode type error. Read https://bytedance.sg.larkoffice.com/docx/MIsKdGOQwoQsnuxrsxEl6AsYgCf
  private observer: MutationObserver;
  // @ts-expect-error TYPE_FIXME. Please Fix the below strict mode type error. Read https://bytedance.sg.larkoffice.com/docx/MIsKdGOQwoQsnuxrsxEl6AsYgCf
  private resizeObserver: ResizeObserver;
  private timer = null;
  private debouncedResize = null;

  private get _infinite() {
    return this.infinite && this.slidesToShow <= 1 && this.slidesToScroll <= 1;
  }

  @Watch('defaultCurrent')
  @Watch('slidesToShow')
  @Watch('slidesToScroll')
  @Watch('infinite')
  handleSlidesToShowChange() {
    this.sliderWidth = this.width * this.slidesToScroll;
    const lastIndex = this.currentIndex;
    this.currentIndex = this.defaultCurrent;
    this.emitCurrentChange(
      this.currentIndex,
      lastIndex,
      'prop',
      this.currentIndex > lastIndex ? 'forward' : 'backward',
    );
    this.renameSlot.call(this);
  }

  @Watch('autoplay')
  handleAutoplayChange() {
    if (this.autoplay) {
      // @ts-expect-error TYPE_FIXME. Please Fix the below strict mode type error. Read https://bytedance.sg.larkoffice.com/docx/MIsKdGOQwoQsnuxrsxEl6AsYgCf
      clearInterval(this.timer);
      // @ts-expect-error TYPE_FIXME. Please Fix the below strict mode type error. Read https://bytedance.sg.larkoffice.com/docx/MIsKdGOQwoQsnuxrsxEl6AsYgCf
      this.timer = setInterval(() => {
        this.clickRightArrow(true);
      }, this.autoplaySpeed);
    } else {
      // @ts-expect-error TYPE_FIXME. Please Fix the below strict mode type error. Read https://bytedance.sg.larkoffice.com/docx/MIsKdGOQwoQsnuxrsxEl6AsYgCf
      clearInterval(this.timer);
    }
  }

  @Watch('currentIndex')
  upDateDotsIndex() {
    this.dotsIndex = 1 + Math.ceil(this.currentIndex / this.slidesToScroll);
  }

  componentWillLoad() {
    this.currentIndex = this.defaultCurrent;
    this.sliderWidth = this.width * this.slidesToScroll;
    this.upDateDotsIndex();
  }

  componentDidLoad() {
    // const observe = watchTargetDescendantNodesEffect(this.el, this.renameSlot.bind(this));
    this.observer = new MutationObserver((mutationsList) => {
      for (const mutation of mutationsList) {
        if (mutation.type === 'childList') {
          this.renameSlot();
        }
      }
    });

    this.resizeObserver = new ResizeObserver(this.onResized.bind(this));

    this.observer.observe(this.el, {
      childList: true, // 监听子元素的变化
    });
    this.resizeObserver.observe(this.el);
    this.containerWidth = getListWidth(this.el);
    this.renameSlot();
    this.handleAutoplayChange();
  }

  private emitCurrentChange(
    current: number,
    last: number,
    trigger: 'arrowButton' | 'pagination' | 'autoplay' | 'prop',
    direction: 'forward' | 'backward',
  ) {
    if (current === last) {
      return;
    }
    this.ksCurrentChange.emit(DetailArgs(current, { trigger, direction } as const));
  }

  private onResized() {
    if (this.debouncedResize) {
      // @ts-expect-error TYPE_FIXME. Please Fix the below strict mode type error. Read https://bytedance.sg.larkoffice.com/docx/MIsKdGOQwoQsnuxrsxEl6AsYgCf
      this.debouncedResize.cancel();
    }
    // @ts-expect-error TYPE_FIXME. Please Fix the below strict mode type error. Read https://bytedance.sg.larkoffice.com/docx/MIsKdGOQwoQsnuxrsxEl6AsYgCf
    this.debouncedResize = debounce(() => this.resizeContainer(), 50);
    // @ts-expect-error TYPE_FIXME. Please Fix the below strict mode type error. Read https://bytedance.sg.larkoffice.com/docx/MIsKdGOQwoQsnuxrsxEl6AsYgCf
    this.debouncedResize();
  }

  private resizeContainer() {
    this.containerWidth = getListWidth(this.el);
    this.width = this.containerWidth / this.slidesToShow;
    this.sliderWidth = this.width * this.slidesToScroll;
    this.height = getListHeight(this.el);
    this.listWidth = this.slidesToShow * this.width * (this.count + Number(this._infinite) * 2 * this.slidesToShow);
  }

  // @ts-expect-error TYPE_FIXME. Please Fix the below strict mode type error. Read https://bytedance.sg.larkoffice.com/docx/MIsKdGOQwoQsnuxrsxEl6AsYgCf
  private autoPlay = (playType) => {
    if (this.timer) {
      clearInterval(this.timer);
    }
    const { autoplaying } = this;
    if (playType === 'update') {
      if (autoplaying === 'hovered' || autoplaying === 'focused' || autoplaying === 'paused') {
        return;
      }
    } else if (playType === 'leave') {
      if (autoplaying === 'paused' || autoplaying === 'focused') {
        return;
      }
    } else if (playType === 'blur') {
      if (autoplaying === 'paused' || autoplaying === 'hovered') {
        return;
      }
    }
    // @ts-expect-error TYPE_FIXME. Please Fix the below strict mode type error. Read https://bytedance.sg.larkoffice.com/docx/MIsKdGOQwoQsnuxrsxEl6AsYgCf
    this.timer = setInterval(this.play, this.autoplaySpeed + 50);
    this.autoplaying = 'playing';
  };

  private play = () => {
    if (dir() === 'ltr' && (this._infinite || this.currentIndex > 0)) {
      this.clickRightArrow(true);
    } else if (this._infinite || hasMoreSlide(this)) {
      this.clickLeftArrow(true);
    }
  };

  // @ts-expect-error TYPE_FIXME. Please Fix the below strict mode type error. Read https://bytedance.sg.larkoffice.com/docx/MIsKdGOQwoQsnuxrsxEl6AsYgCf
  private pause = (pauseType) => {
    if (this.timer) {
      clearInterval(this.timer);
      this.timer = null;
    }
    const { autoplaying } = this;
    if (pauseType === 'paused') {
      this.autoplaying = 'paused';
    } else if (pauseType === 'focused') {
      if (autoplaying === 'hovered' || autoplaying === 'playing') {
        this.autoplaying = 'focused';
      }
    } else {
      // pauseType  is 'hovered'
      if (autoplaying === 'playing') {
        this.autoplaying = 'hovered';
      }
    }
  };

  private onDotsOver = () => this.autoplay && this.pause('hovered');
  private onDotsLeave = () => this.autoplay && this.autoplaying === 'hovered' && this.autoPlay('leave');
  private onTrackOver = () => this.autoplay && this.pause('hovered');
  private onTrackLeave = () => {
    this.autoplay && this.autoplaying === 'hovered' && this.autoPlay('leave');
  };
  private onSlideFocus = () => this.autoplay && this.pause('focused');
  private onSlideBlur = () => this.autoplay && this.autoplaying === 'focused' && this.autoPlay('blur');

  disconnectedCallback() {
    // @ts-expect-error TYPE_FIXME. Please Fix the below strict mode type error. Read https://bytedance.sg.larkoffice.com/docx/MIsKdGOQwoQsnuxrsxEl6AsYgCf
    clearInterval(this.timer);
  }

  private renameSlot() {
    Array.from(this?.el.children).forEach((item, index) => {
      item.slot = `carousel-${index}`;
      // @ts-expect-error TYPE_FIXME. Please Fix the below strict mode type error. Read https://bytedance.sg.larkoffice.com/docx/MIsKdGOQwoQsnuxrsxEl6AsYgCf
      item.onmouseover = this.onSlideFocus.bind(this);
      // @ts-expect-error TYPE_FIXME. Please Fix the below strict mode type error. Read https://bytedance.sg.larkoffice.com/docx/MIsKdGOQwoQsnuxrsxEl6AsYgCf
      item.onmouseleave = this.onSlideBlur.bind(this);
    });
    this.width = this.containerWidth / this.slidesToShow;
    this.sliderWidth = this.width * this.slidesToScroll;
    this.height = getListHeight(this.el);
    this.count = this?.el.children?.length;
    this.dotsCount = getDotCount({
      slideCount: this.count,
      slidesToScroll: this.slidesToScroll,
      slidesToShow: this.slidesToShow,
      infinite: this._infinite,
    });
    if (this._infinite) {
      const lastChildList = Array.from(this?.el.children)
        .slice(0, this.slidesToShow)
        .map((item) => {
          const dom = document.createElement('div');
          dom.style.width = `${this.width}px`;
          dom.style.flexShrink = '0';
          dom.appendChild(item.cloneNode(true));
          dom.onfocus = this.onSlideFocus.bind(this);
          dom.onblur = this.onSlideBlur.bind(this);
          return dom;
        });
      const firstChildList = Array.from(this?.el.children)
        .slice(this.count - this.slidesToShow, this.count)
        .map((item) => {
          const dom = document.createElement('div');
          dom.style.width = `${this.width}px`;
          dom.style.flexShrink = '0';
          dom.appendChild(item.cloneNode(true));
          dom.onfocus = this.onSlideFocus.bind(this);
          dom.onblur = this.onSlideBlur.bind(this);
          return dom;
        });
      this.last?.replaceChildren(...lastChildList);
      this.first?.replaceChildren(...firstChildList);
    }

    this.listWidth = this.slidesToShow * this.width * (this.count + Number(this._infinite) * 2 * this.slidesToShow);
    forceUpdate(this.el);
  }

  private renderCarousel() {
    const itemList = Array.from(this?.el.children)?.map((_, index) => (
      <div key={index} style={{ width: `${this.width}px` }} data-testid={`ks-carousel-index-cDdYjP-${index}`}>
        <slot name={`carousel-${index}`}></slot>
      </div>
    ));
    return (
      <Fragment>
        {this._infinite && (
          <div
            key="first"
            class={'first'}
            ref={(el) => (this.first = el)}
            style={{ width: `${this.slidesToShow * this.width}px`, float: 'left', display: 'flex', overflow: 'hidden' }}
            data-testid="ks-carousel-index-47jCpv"
          ></div>
        )}

        {itemList}
        {this._infinite && (
          <div
            key="last"
            class={'last'}
            ref={(el) => (this.last = el)}
            style={{ width: `${this.slidesToShow * this.width}px`, float: 'left', display: 'flex', overflow: 'hidden' }}
            data-testid="ks-carousel-index-3Gwhha"
          ></div>
        )}
      </Fragment>
    );
  }

  private clickLeftArrow = (triggeredByAutoPlay?: boolean) => {
    const lastIndex = this.currentIndex;
    if (this.currentIndex >= this.slidesToScroll) {
      this.currentIndex = this.currentIndex - this.slidesToScroll;
    } else if (this._infinite) {
      const tempCurrent = this.currentIndex - this.slidesToScroll;
      this.currentIndex = this.count + Math.max(-this.slidesToShow, tempCurrent);
    } else {
      this.currentIndex = 0;
    }
    this.emitCurrentChange(this.currentIndex, lastIndex, triggeredByAutoPlay ? 'autoplay' : 'arrowButton', 'backward');
    this.clickArrow = 'left';
  };

  private clickRightArrow = (triggeredByAutoPlay?: boolean) => {
    const lastIndex = this.currentIndex;
    if (this.currentIndex + this.slidesToShow < this.count - this.slidesToScroll) {
      this.currentIndex = this.currentIndex + this.slidesToScroll;
    } else if (this._infinite) {
      const tempCurrent = this.currentIndex + this.slidesToScroll;
      this.currentIndex = tempCurrent >= this.count ? 0 : tempCurrent;
    } else {
      this.currentIndex = this.count - this.slidesToShow;
    }
    this.emitCurrentChange(this.currentIndex, lastIndex, triggeredByAutoPlay ? 'autoplay' : 'arrowButton', 'forward');
    this.clickArrow = 'right';
  };

  // @ts-expect-error TYPE_FIXME. Please Fix the below strict mode type error. Read https://bytedance.sg.larkoffice.com/docx/MIsKdGOQwoQsnuxrsxEl6AsYgCf
  private handleArrowButtonClick(e) {
    const { detail }: { detail: string } = e;
    if (this.autoplay) {
      // @ts-expect-error TYPE_FIXME. Please Fix the below strict mode type error. Read https://bytedance.sg.larkoffice.com/docx/MIsKdGOQwoQsnuxrsxEl6AsYgCf
      clearInterval(this.timer);
    }
    if (detail === 'left') {
      this.clickLeftArrow();
    } else {
      this.clickRightArrow();
    }
  }

  render() {
    return (
      <Host dir={dir()} ks-carousel>
        <ks-inner-slider
          clickArrow={this.clickArrow}
          count={this.count}
          currentIndex={this.currentIndex}
          listWidth={this.listWidth}
          height={this.height}
          sliderWidth={this.width}
          slidesToScroll={this.slidesToScroll}
          slidesToShow={this.slidesToShow}
          infinite={this._infinite}
        >
          {this.renderCarousel()}
        </ks-inner-slider>
        {this.arrows && (
          <ks-arrow-button-group
            onKsChange={this.handleArrowButtonClick.bind(this)}
            currentIndex={this.currentIndex}
            slidesToShow={this.slidesToShow}
            count={this.count}
            infinite={this._infinite}
            orient="left"
            arrows={this.arrows}
            onKsArrowOver={this.onTrackOver.bind(this)}
            onKsArrowLeave={this.onTrackLeave.bind(this)}
            onKsArrowEnter={this.onTrackLeave.bind(this)}
            bulletinMode={this.bulletinMode}
            data-testid="ks-carousel-index-kt2aFL"
          />
        )}

        {(this.pagination === 'numeric' || (this.pagination === true && this.dotsCount > 6)) && (
          <ks-carousel-arrow-pagination
            onKsChange={this.handleArrowButtonClick.bind(this)}
            count={this.dotsCount}
            currentIndex={this.dotsIndex}
            slidesToShow={this.slidesToShow}
            infinite={this._infinite}
            onKsArrowOver={this.onTrackOver.bind(this)}
            onKsArrowLeave={this.onTrackLeave.bind(this)}
            onKsArrowEnter={this.onTrackLeave.bind(this)}
            data-testid="ks-carousel-index-aNUY1x"
          />
        )}

        {(this.pagination === 'dots' || (this.pagination === true && this.dotsCount <= 6)) && (
          <ks-dots
            class={{ 'bulletin-mode': this.bulletinMode }}
            count={this.dotsCount}
            currentIndex={this.dotsIndex}
            onKsChange={(e) => {
              const { detail } = e;
              const lastIndex = this.currentIndex;
              this.currentIndex = this.currentIndex + (detail as number) * this.slidesToScroll;
              this.emitCurrentChange(
                this.currentIndex,
                lastIndex,
                'pagination',
                this.currentIndex > lastIndex ? 'forward' : 'backward',
              );
              this.clickArrow = 'none';
            }}
            onKsDotsOver={this.onDotsOver.bind(this)}
            onKsDotsLeave={this.onDotsLeave.bind(this)}
            onKsDotsEnter={this.onDotsLeave.bind(this)}
            data-testid="ks-carousel-index-eLjmrW"
          />
        )}
      </Host>
    );
  }
}
